// TH16 v1.00a Stage 3 boss, spell 22-25 "犬符「野良犬の散歩」".
// Source: st03bs.ecl.txt:472-536 BossCard1 (entry) + 538-603 BossCard1_at (dependency).
// Shell from validation.md; source spell window 1920 frames after the 120-frame opening buffer.

const TIME_LIMIT: int = 2044;
const OPENING_BUFFER: int = 120;

// etSprite(0,20,6) then EX SETSPRITE a=20 b=1 at effect entry -> TH16 type 20 oval, color 1.
const TH16_OVAL: int = 672;

// BossCard1_at:571 etDist(0,64) plus EX ANIM a=1 recoil 4*1.5px along the shot angle.
const SPAWN_DIST: fx = 58fx;
// BossCard1_at:572-573 %A starts at 1.5707964f and advances by 3.883222 rad per shot.
const ANGLE_STEP: int = 40503;

// BossCard1_at:549 EX OFFSCREEN a=160 b=0: the source bullet keeps at most 160 frames.
xformdef DOG_LIFE {
    offscreen_keep(160);
    wait(160);
    set_life(1);
}

// BossCard1_at EX program: STEP a=60 b=rank s=rank + VELTIME a=90 r=2.0, one bullet each.
async sub dog_bullet() {
    var rank: int = global(GVAR_RANK);
    var seg_max: int = 4;
    var seg_speed: fx = 1.8fx;
    if rank == RANK_EASY {
        seg_max = 2;
    } else if rank == RANK_NORMAL {
        seg_max = 3;
    } else if rank == RANK_LUNATIC {
        seg_speed = 2.2fx;
    }

    var dir: angle = $self_angle;       // segment angle, re-aimed with STEP c=1
    var scal: fx = 1.5fx;               // source logical scalar speed
    var delta: fx = 0.0055556fx;        // VELTIME (2.0-1.5)/90
    var seg_t: int = 0;
    var segs: int = 0;
    var vt: int = 0;

    loop {
        if segs >= seg_max {            // STEP exhausted: keep the last written velocity
            wait(1);
            continue;
        }
        // STEP: v = speed - t*speed/a along the current angle.
        var v: fx = scal - (seg_t as fx) * scal / 60fx;
        // VELTIME: scalar speed ramps toward 2.0 and adds delta along the direction.
        if vt < 90 {
            v = v + delta;
            scal = scal + delta;
            vt = vt + 1;
        }
        set_vel(0, v * cos(dir), v * sin(dir));
        seg_t = seg_t + 1;
        if seg_t >= 60 {                // segment boundary: re-aim at player, restore speed
            seg_t = 0;
            segs = segs + 1;
            if segs < seg_max {
                dir = atan2($player_y - $self_y, $player_x - $self_x);
                scal = seg_speed;
            }
        }
        wait(1);
    }
}

async sub source_boss() {
    set_invuln(65535);
    set_hitbox(24fx);                   // Boss(): setHitbox(48,48)
    set_hurtbox(20fx);                  // Boss(): setHurtbox(40,40)

    // BossCard1:507 movePosTime(60,4,0,128); :509 moveLimit(0,128,240,64) is never
    // reached because the boss stays at the limit centre for the whole card.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    wait(60);                           // BossCard1:+120 -> first BossCard1_at call

    // BossCard1_at:574-591 floatTime(1,%C,840,0,start,goal): the shot interval ramps
    // linearly over 840 frames and is read as _S(%C) before each wait.
    var iv_start: fx = 10fx;
    var iv_goal: fx = 2fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        iv_goal = 5fx;
    } else if rank == RANK_LUNATIC {
        iv_start = 7fx;
    }
    var dir: int = 16384;               // %A = 1.5707964f
    var src: int = 120;                 // source clock; the +120 label fires the first shot

    while src < 1920 {                  // setInterrupt(0,0,1920,"Boss2"): segment window
        // BossCard1_at:1060 etAngle(0,%A,0); etOn(0) -- fixed-direction ring, 1 way.
        var x: fx = $self_x + SPAWN_DIST * cos(dir as angle);
        var y: fx = $self_y + SPAWN_DIST * sin(dir as angle);
        _ = fire(TH16_OVAL, 1, x, y, 1.5fx, dir as angle, DOG_LIFE, dog_bullet);
        dir = dir + ANGLE_STEP;

        var e: int = src - 120;
        if e > 840 { e = 840; }
        var v: fx = iv_start + (iv_goal - iv_start) * (e as fx) / 840fx;
        var iv: int = v as int;
        if iv < 1 { iv = 1; }
        wait(iv);
        src = src + iv;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, source_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
